function addPartida(e){e.preventDefault();let f=new FormData(e.currentTarget);setD(obraId,d=>({...d,partides:[...d.partides,{codi:f.get("codi"),cap:f.get("cap"),concepte:f.get("concepte"),ut:f.get("ut"),q:+f.get("q")||0,pu:+f.get("pu")||0,certAnterior:0,certActual:0,tipus:f.get("tipus")}]}));setModal(null)}
function addObra(e){e.preventDefault();let f=new FormData(e.currentTarget),id="obra-"+Date.now();let o={id,client:f.get("client"),any:f.get("any"),nom:f.get("nom"),subtitol:f.get("subtitol"),tipologia:f.get("tipologia"),estat:f.get("estat"),pressupost:0,certificacio:0,propietat:f.get("propietat"),nifPropietat:f.get("nifPropietat"),adreca:f.get("adreca"),poblacio:f.get("poblacio"),rc:f.get("rc"),imatge:"",properaCert:"Pendent",properaVisita:"Pendent"};setObres(p=>[o,...p]);setD(id,empty());setModal(null);openObra(id)}
function addClient(e){e.preventDefault();let f=new FormData(e.currentTarget),id="client-"+Date.now();let c={id,nom:f.get("nom"),rao:f.get("rao"),tipus:f.get("tipus"),contacte:f.get("contacte"),nif:f.get("nif"),email:f.get("email"),telefon:f.get("telefon"),adreca:f.get("adreca"),color:"blue",logo:f.get("logoPreview")||""};setClients(p=>[c,...p]);setModal(null);openClient(id)}
function addEvent(e){e.preventDefault();let f=new FormData(e.currentTarget);setD(obraId,d=>({...d,events:[...d.events,{id:"e"+Date.now(),day:+f.get("day"),month:+f.get("month"),year:+f.get("year"),title:f.get("title"),type:f.get("type"),hora:f.get("hora"),note:f.get("note"),color:f.get("color")}]}));setModal(null)}
function addManualHours(e){e.preventDefault();let f=new FormData(e.currentTarget);let hi=f.get("inici"),hf=f.get("final");let h=calcHours(hi,hf);setD(obraId,d=>({...d,hores:[...d.hores,{id:"h"+Date.now(),data:f.get("data"),etiqueta:f.get("etiqueta"),tasca:f.get("tasca"),inici:hi,final:hf,hores:h,preu:+f.get("preu")||50}]}))}
function startTimer(){setTimer(t=>({...t,running:true,start:Date.now(),elapsed:0}))}
function stopTimer(){let h=Math.max(timer.elapsed/3600000,0.01);setD(obraId,d=>({...d,hores:[...d.hores,{id:"h"+Date.now(),data:new Date().toLocaleDateString("ca-ES"),etiqueta:timer.label,tasca:timer.task||"Temps cronometrat",inici:"—",final:"—",hores:h,preu:+timer.rate||50}]}));setTimer(t=>({...t,running:false,start:null,elapsed:0,task:""}))}
function deleteHour(id){setD(obraId,d=>({...d,hores:d.hores.filter(h=>h.id!==id)}))}
function calcHours(a,b){let [ah,am]=String(a).split(":").map(Number),[bh,bm]=String(b).split(":").map(Number);let mins=(bh*60+bm)-(ah*60+am);return Math.max(mins/60,0)}


